{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "Rufinamide, a close analogue with a fluorobenzyl triazole and carboxamide, has absolute oral bioavailability of approximately 70–85% in pediatric and adult patients, and food increases its absorption; this supports high F for the query under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Trovafloxacin, a fluorinated heteroaromatic drug, has mean absolute oral bioavailability of 87.6% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Meloxicam has absolute oral bioavailability of 89% in humans, supporting high F for a structurally related heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Ketanserin, despite first-pass metabolism, has absolute oral bioavailability of about 50%, still well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Safinamide has absolute oral bioavailability of 95% with absorption not appreciably influenced by food, supporting high F under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Dabrafenib, which shares an aminopyrimidine and fluorophenyl/heteroaryl motif, has absolute oral bioavailability of 94.5% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Alfuzosin under fed conditions has absolute oral bioavailability of 49%, above the 20% threshold, supporting high F for the fed-state query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Diclofenac has mean absolute oral bioavailability of 65.1% in adults, with reported values ranging from about 35% to 90% depending on formulation, all above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved analogues with high assay-transfer scores show absolute oral bioavailability well above 20% (mostly 49–95%), including under fed conditions; no evidence supports F <20%, so the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule.",
    "Fed-state effect for the query is inferred from analogues rather than measured directly.",
    "Some analogues show formulation-dependent F, but all remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

